styles.css:
@font-face{font-family:'Inter';font-style:normal;font-weight:300 800;font-display:swap;src:url(https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800) format('woff2');}
@font-face{font-family:'JetBrains Mono';font-style:normal;font-weight:400 500;font-display:swap;src:url(https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500) format('woff2');}
body,input,textarea,select,button{font-family:'Inter',sans-serif;}
:root{--pdf-body:#e8e8e8;--pdf-muted-2:#bdbdbd;--pdf-surface:#161616;--pdf-surface-2:#1d1d1d;--pdf-grain-opacity:0;}
body{background-color:#0b0b0b;color:#f5f5f5;font-size:var(--wp--preset--font-size--large);line-height:1.6;}
.pdf-kicker,.pdf-stat-num,.pdf-stat-lbl,.pdf-drow-date,.pdf-drow-cat,.pdf-tab,.pdf-share-link,.pdf-share-label,.pdf-response-nav a,.pdf-article-kicker,.pdf-article-accent,.pdf-article .wp-block-post-content h2::before,.pdf-article .wp-block-post-content > p:first-of-type::first-letter{font-family:'JetBrains Mono',monospace;}
body::before{display:none;}
